__NUXT_JSONP__("/de/stay", (function(a,b,c,d,e,f,g,h,i){return {data:[{details:{slug:"de",pageTitle:"Unterkünfte | Mentor Language Institute",pageDescription:"MLI arbeitet mit der US-amerikanischen Support Services Inc. zusammen, um MLI-Studenten eine Unterkunft zu bieten.",title:"Unterkünfte",subtitle:["MLI arbeitet mit der US-amerikanischen Support Services Inc. zusammen, um MLI-Studenten eine Unterkunft zu bieten. \u003Cbr \u002F\u003E Weitere Informationen finden Sie unter \u003Ca href=\"www.usssinc.net\" target=\"_blank\"\u003Ewww.usssinc.net\u003C\u002Fa\u003E"],image:"\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-1.jpg",gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-3.jpg"],note:"Studenten können wählen zwischen Gastfamilien oder Studentenwohnheimen.",types:[{title:"Studentenwohnheim",description:["Wir bieten 40 Zimmer in unseren Studentenwohnheimen an. Dort hat man sehr viele Gelegenheiten sich mit anderen internationalen Studenten auszutauschen. Wir empfehlen dir in ein Sudentenwohnheim zu gehen, wenn du ein begrenztes Budget hast."],lists:["\u003Cb\u003EZimmer\u003C\u002Fb\u003E : Privatzimmer (Einzelzimmer), Zweierzimmer (2 Personen) und Viererzimmer (4 Personen)","\u003Cb\u003EVerpflegung\u003C\u002Fb\u003E : Keine Mahlzeiten inbegriffen (eine voll ausgestattete Küche ist vorhanden)","\u003Cb\u003EPrivatsphäre\u003C\u002Fb\u003E : Es gibt etwas mehr Privatsphäre als in Gastfamilien. Es gibt einige Regeln im Studentenwohnheim.","\u003Cb\u003EAnbindung\u003C\u002Fb\u003E : ungefähr 20 Minuten zu Fuss oder mit dem Bus."],gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-1.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-3.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-4.jpg"],prices:[{title:"Studentenwohnheimpreise",table:{tableMaxCol:4,title:"Platzierungsgebühr* : $200\u003Cbr \u002F\u003E Wenn Sie jünger als 18 Jahre alt sind, liegt die Miete etwa 10 % über dem Preis für eine Person, die älter als 18 Jahre ist.",thead:[b,c,"Zweierzimmer","Viererzimmer"],tbody:[["\u003Cb\u003E Kaution**\u003C\u002Fb\u003E",a,a,a],[d,"$550","$410",a],[e,"$1,100","$820","$600"],[f,"$1,650","$1,230","$900"],[g,"$2,200","$1,640","$1,200"],[h,"$4,160","$2,960","$2,160"],[i,"$6,240","$4,440","$3,240"]]},notes:["*Die Platzierungsgebühr ist eine Einmalzahlung. Sie wird nicht zurückerstattet.\u003Cbr \u002F\u003E**Die Kaution wird nach dem Auszug der Studenten zurückerstattet."]}]},{title:"Gastfamilien",description:["Studenten, die sich für eine Gastfamilie entscheiden, suchen nach einer sicheren, offenen und komfortablen Atmosphäre, in der sie ihre Englischkenntnisse trainieren können. Es ist ausserdem eine gute Gelegenheit, um über amerikanische Bräuche, Traditionen und Familienwerte zu lernen."],lists:["\u003Cb\u003EZimmer\u003C\u002Fb\u003E : Privatzimmer (Einzelzimmer)","\u003Cb\u003EVerpflegung\u003C\u002Fb\u003E : 2 Mahlzeiten pro Tag (Frühstück und Abendessen)","\u003Cb\u003EPrivatsphäre\u003C\u002Fb\u003E : Abhängig von der Gastfamilie gibt es ein paar Hausregeln.","\u003Cb\u003EAnbindung\u003C\u002Fb\u003E : 30- 45 Minuten mit dem Bus"],gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-1.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-3.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-4.jpg"],prices:[{title:"Gastfamilienpreise",table:{tableMaxCol:3,title:"Platzierungsgebühr* : $300\u003Cbr \u002F\u003E Wenn Sie jünger als 18 Jahre alt sind, liegt die Miete etwa 10 % über dem Preis für eine Person, die älter als 18 Jahre ist.",thead:[b,c,"Zweierzimmer***"],tbody:[["\u003Cb\u003EKaution**\u003C\u002Fb\u003E",a,a],[d,"$436","$384"],[e,"$872","$768"],[f,"$1,308","$1,152"],[g,"$1,744","$1,536"],[h,"$3,160","$2,904"],[i,"$4,740","$4,356"]]},notes:["*Die Platzierungsgebühr ist eine Einmalzahlung. Sie wird nicht zurückerstattet.\u003Cbr \u002F\u003E**Die Kaution wird nach dem Auszug der Studenten zurückerstattet.\u003Cbr \u002F\u003E***Wenn du dich für ein geteiltes Zimmer in einer Gastfamilie bewirbst, musst du dich mit einer zweiten Person anmelden."]}]}],comments:{title:"Kommentare unserer Mitarbeiter",description:["Es ist nicht einfach eine Unterkunft zu finden, wenn man in den USA ankommt, \u003Cbr \u002F\u003Evor allem für internationale Studenten, da sie über keine Social Security Number (SSN, Sozialverischerungsnummer) und keine credit history (Belege für Kreditwürdigkeit in den USA) verfügen. \u003Cbr \u002F\u003EMeistens erfordert das Mieten einer Wohnung eine SSN und eine credit history. \u003Cbr \u002F\u003EDeswegen empfehlen wir dir in einer unserer Unterkünfte zu bleiben, zumindest für die ersten paar Monate.","※Deine Unterkunft wird von U.S. Support Service Inc. oder anderen Partnern zur Verfügung gestellt."]},dir:"\u002Fstay",path:"\u002Fstay\u002Fde",extension:".json",createdAt:"2026-10-22T16:31:31.084Z",updatedAt:"2025-05-26T12:06:27.918Z"}}],fetch:{},mutations:void 0}}("$300","","Privatzimmer","1 Woche","2 Wochen","3 Wochen","4 Wochen","8 Wochen","12 Wochen")));